def getDadosCidade(cod_ibge):
    aux = [item for item in cidades_tempo if item[0] == str(cod_ibge)]
    return(aux[0])


def getInformacoesChuva(cod_ibge):
    with open(ARQUIVOS + "previsao-tempo/coordenadas_municipios.json") as f:
        municipios = json.load(f)
    coordenadas = ""
    for municipio in municipios:
        if str(municipio['codigo_ibge']) == cod_ibge:
            coordenadas = str(municipio['latitude']) + ',' + str(municipio['longitude'])

    url = "https://atlas.microsoft.com/weather/forecast/daily/json?subscription-key=rZE1vWuQ5tjwxZRScwel2_dyAxlFpBRL2mnKEzTLxPo&api-version=1.0&query=%s&unit=metric&duration=10&language=pt-br" % (coordenadas)
    f = requests.get(url)
    dados = f.json()
    saida = {}
    dias = dados['forecasts']
    for dia in dias:
        data = dia['date']
        data = data.split('T')
        data = data[0]
        data = datetime.datetime.strptime(data, "%Y-%m-%d")
        data_str = data.strftime("%d/%m/%Y")
        chuva = dia['day']['rainProbability']
        saida[data_str] = chuva
    return {"codigo_ibge": cod_ibge, "dados": saida}




def getTempoCidadeDia(cod_ibge, data):

    url = "https://apiprevmet3.inmet.gov.br/previsao/" + cod_ibge
    f = requests.get(url)
    dias = {}
    contador = 0
    while (f.status_code != 200) and (contador < 10):
        url = "https://apiprevmet3.inmet.gov.br/previsao/" + cod_ibge
        f = requests.get(url)
        contador = contador + 1
        time.sleep(2)

    if f.status_code == 200:
        dados = f.json()

        for dia in dados[cod_ibge]:
            if dia == data:
                turnos = dados[cod_ibge][dia]
                #print(cod_ibge)
                if 'manha' in turnos or 'tarde' in turnos or 'noite' in turnos:
                    turno = 'tarde'
                    # resumo = turnos[turno]['resumo']
                    resumo = ""
                    tempo = turnos[turno]['tempo']
                    temp_max = turnos[turno]['temp_max']
                    temp_min = turnos[turno]['temp_min']
                    cod_icone = turnos[turno]['cod_icone']
                    if cod_icone in icones:
                        icone = icones[cod_icone]
                    else:
                        icone = "0"
                    umidade_max = turnos[turno]['umidade_max']
                    umidade_min = turnos[turno]['umidade_min']
                    dias = {"descricao": resumo, "tempo": tempo, "maxima": temp_max, "minima": temp_min, "icone": icone, "umidade_max": umidade_max, "umidade_min": umidade_min}
                else:
                    # resumo = turnos['resumo']
                    resumo = ""
                    tempo = turnos['tempo']
                    temp_max = turnos['temp_max']
                    temp_min = turnos['temp_min']
                    cod_icone = turnos['cod_icone']
                    if cod_icone in icones:
                        icone = icones[cod_icone]
                    else:
                        icone = "0"
                    umidade_max = turnos['umidade_max']
                    umidade_min = turnos['umidade_min']
                    #print(cod_icone, icone, resumo)
                    # if icone == "0":
                    #     print(cod_icone, icone, resumo)
                    dias = {"descricao": resumo, "tempo": tempo, "maxima": temp_max, "minima": temp_min, "icone": icone, "umidade_max": umidade_max, "umidade_min": umidade_min}

    else:
        print("Erro: ", cod_ibge)
    time.sleep(1)
    return dias
